import{_ as r,o as a,c as e,ai as o}from"./chunks/framework.ampVZV4B.js";const c=JSON.parse('{"title":"项目复盘模板与方法","description":"","frontmatter":{},"headers":[],"relativePath":"ai/business/retro-notes.md","filePath":"ai/business/retro-notes.md"}'),s={name:"ai/business/retro-notes.md"};function l(n,t,i,d,h,g){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="项目复盘模板与方法" tabindex="-1">项目复盘模板与方法 <a class="header-anchor" href="#项目复盘模板与方法" aria-label="Permalink to “项目复盘模板与方法”">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>做副业探索的人，大多数项目会以「不继续」收场——这不是失败率异常，而是探索的正常形态。真正拉开差距的不是谁失败得少，而是<strong>失败之后留下了什么</strong>。很多人做过的典型循环是：兴奋启动 → 没数据 → 心灰意冷地关掉 → 三个月后想不起任何细节 → 下一个项目从零开始犯同样的错。时间花了，什么都没沉淀，等于白亏。</p><p>这篇给一套能坚持下来的复盘方法：一个填得完的模板、几条复盘纪律、哪些东西值得沉淀成资产，以及怎么把「失败项目」重新定义成经验。原则：<strong>复盘必须轻到你愿意做第二次</strong>——写三千字精美报告的复盘法，第一次就是最后一次。</p><h2 id="拆解" tabindex="-1">拆解 <a class="header-anchor" href="#拆解" aria-label="Permalink to “拆解”">​</a></h2><h3 id="_1-复盘模板-五个区块-30-分钟填完" tabindex="-1">1. 复盘模板：五个区块，30 分钟填完 <a class="header-anchor" href="#_1-复盘模板-五个区块-30-分钟填完" aria-label="Permalink to “1. 复盘模板：五个区块，30 分钟填完”">​</a></h3><p>在项目停止（或到达里程碑）的一周内，趁记忆新鲜填完：</p><p><strong>区块一：目标 vs 结果</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>当初的目标</td><td>启动时写下的那句话，照抄原文</td></tr><tr><td>事前预期</td><td>预计的指标、时间、收入（当时拍的数字）</td></tr><tr><td>实际结果</td><td>真实数据，如实填，不修饰</td></tr><tr><td>差距</td><td>最大的落差在哪一项</td></tr></tbody></table><p>照抄原文很重要——事后人会悄悄篡改「我当初本来就想……」。原始预期与结果的差距，正是认知更新的幅度。</p><p><strong>区块二：关键决策记录</strong></p><p>回看项目过程，列出 3-5 个真正改变走向的决策点：当时的选项是什么、为什么这么选、结果如何、<strong>以现在所知本应该怎么选</strong>。例如「选了先做产品后找用户」「定价 299 没敢定 99」「渠道选了发论坛而不是找社群」。决策记录是复盘里价值最高的部分，因为它校准的是你的判断力，而判断力会复用到下个项目。</p><p><strong>区块三：数据与证据</strong></p><p>把硬证据归档：落地页截图、访问/转化数据、和用户聊天的原话、订单记录。不求全，求「半年后还能还原当时发生了什么」。用户原话尤其要留——那些「我不会为这个付钱因为……」的句子，是花钱都买不到的需求认知。</p><p><strong>区块四：可复用资产清单</strong></p><p>逐项点算这次留下的东西（详见下一节）。</p><p><strong>区块五：一句话结论</strong></p><p>用一句话给项目定性，三选一：</p><ul><li>方向问题（需求不成立）→ 下次先验证再动手；</li><li>执行问题（需求成立，我做砸了）→ 补执行，方向可再试；</li><li>时机/资源问题（成立但现在做不了）→ 记入待办，等条件。</li></ul><h3 id="_2-可复用资产-失败项目的「回本」方式" tabindex="-1">2. 可复用资产：失败项目的「回本」方式 <a class="header-anchor" href="#_2-可复用资产-失败项目的「回本」方式" aria-label="Permalink to “2. 可复用资产：失败项目的「回本」方式”">​</a></h3><p>一个项目停了，这些东西不该跟着消失：</p><ul><li><strong>代码与脚本</strong>：哪怕产品死了，里面的登录、支付对接、爬虫、部署脚本大概率能进你的工具库。整理归档，标好用途；</li><li><strong>内容素材</strong>：过程中写的所有介绍文案、教程、截图，可以改写成技术文章发出去——「我做了个没成的产品，过程复盘如下」本身是开发者社区爱看的内容；</li><li><strong>渠道与人脉</strong>：发过帖的平台、加过的产品群、聊过的潜在用户，记下来，下个项目冷启动时直接复用；</li><li><strong>流程模板</strong>：这次踩着走通的「落地页怎么发、预售怎么收款、社群怎么运营」，改改就是下个项目的标准作业程序；</li><li><strong>认知结论</strong>：「这个人群不为此付费」「论坛渠道转化远低于社群」这类判断，直接更新进你的需求筛选标准（见「从身边挖掘真实需求」）。</li></ul><p><strong>判断复盘质量的唯一标准：这次项目停掉之后，下一个项目的启动成本是否降低了。</strong> 资产清单越实，说明这次探索越值。</p><h3 id="_3-失败项目如何转化为经验" tabindex="-1">3. 失败项目如何转化为经验 <a class="header-anchor" href="#_3-失败项目如何转化为经验" aria-label="Permalink to “3. 失败项目如何转化为经验”">​</a></h3><p>三步完成转化：</p><ol><li><strong>归档</strong>：把模板五个区块 + 证据放进统一目录（如 <code>~/projects/_retro/&lt;项目名&gt;/</code>），从此项目正式「关闭」，不许再凭情绪反复横跳（要么重启、要么归档，二选一）；</li><li><strong>公开</strong>：挑一两条认知写成短文发出去。公开复盘有两个副作用：一是逼自己把逻辑讲顺（讲不顺就是没想明白），二是它本身就是个人品牌内容——<strong>诚实的失败复盘比成功学更涨信任</strong>；</li><li><strong>更新规则</strong>：把认知写回你的判断标准里。下次做机会打分时，「这类人群不付费」就是一个可以打分的维度，而不是重新踩一遍的坑。</li></ol><p><strong>需要警惕的一种「假复盘」</strong>：把结论全部归因为外部——平台不行、用户不懂、运气不好。有效的复盘必须至少有一条指向自己可控的因素（我的判断、我的排序、我的执行），否则这个项目等于没复盘。</p><h3 id="_4-复盘纪律-让这个习惯活得下来" tabindex="-1">4. 复盘纪律：让这个习惯活得下来 <a class="header-anchor" href="#_4-复盘纪律-让这个习惯活得下来" aria-label="Permalink to “4. 复盘纪律：让这个习惯活得下来”">​</a></h3><ul><li><strong>时机</strong>：停止后一周内，超过一个月记忆就已失真；</li><li><strong>时长</strong>：30 分钟封顶，模板已替你结构化，别写散文；</li><li><strong>触发</strong>：把它和「关闭项目」这个动作绑定——不复盘不算关闭；</li><li><strong>回顾</strong>：每启动一个新项目前，花 10 分钟翻一遍过往复盘的「一句话结论」，这是这套系统真正开始产生复利的时刻。</li></ul><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>复盘的价值不在评判过去，而在降低下一个项目的启动成本——这是唯一的质量标准；</li><li>五区块模板 30 分钟填完：目标 vs 结果（照抄原文防篡改）、关键决策、证据归档、资产清单、一句话定性；</li><li>可复用资产五类：代码、内容素材、渠道人脉、流程模板、认知结论；</li><li>失败转化三步：归档（关闭即不反复）、公开（逼自己讲顺 + 涨信任）、更新规则（写回筛选标准）；</li><li>避免全甩外部的假复盘——每份至少留一条指向自己可控因素的结论；新项目启动前先翻旧结论。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>副业探索本质上是一场批量实验，而复盘是实验记录本。没有记录的实验，失败一百次也只是一百次挫败；有记录的实验，每次失败都在为下一次降低门槛。把它做得足够轻——30 分钟、五区块、关闭即归档——你就能一直做下去。<strong>探索者真正的护城河，不是没失败过，而是每个失败都变成了下一次的起跑线。</strong></p>',33)])])}const _=r(s,[["render",l]]);export{c as __pageData,_ as default};
